import {performanceCard} from './performance.js';
import {FUNDS,ACCOUNTS,money,percent,project,totalCost} from './core.js';
export const newGoals=[['wealth','Grow my money','Build wealth over time','↗'],['retirement','Plan my retirement','Invest for your future income','◷'],['goal','Reach a goal','Turn your plans into progress','⚑'],['explore','Get started','Take your first investment step','✦']];
export const newQuestions=[
 {id:'goal',t:'What would you like to achieve?',s:'Let’s give your investment a purpose.',o:newGoals.map(([v,t,s])=>[v,t,s]),h:'Having a goal makes it easier to stick with regular investing.',fact:'A regular contribution can turn investing into a habit. You don’t need to wait for a large lump sum.'},
 {id:'age',t:'Let’s start with your age.',s:'This helps us match the account’s access rules to your plans.',f:[['age','Your age',16,100]],h:'Your age helps us put retirement account options in context.',fact:'A retirement annuity can offer tax relief on qualifying contributions. Most of the money is reserved for retirement.'},
 {id:'amounts',t:'How much would you like to invest?',s:'Choose an amount you can comfortably set aside. Monthly, once-off, or both.',f:[['monthly','Every month (R)',0,1000000],['lump','Initial lump sum amount (R)',0,100000000]],h:'Monthly contributions keep your plan moving. A lump sum gives it a head start.',fact:'Your contributions can earn growth. When that growth stays invested, it can earn growth too.'},
 {id:'access',t:'How much access would you like?',s:'This helps us choose between flexible and longer-term accounts.',o:[['flexible','I want to keep it flexible','I may want to withdraw before my goal date'],['retirement','I can leave it until retirement','This money is for my later years'],['locked','I can commit for five years or more','I don’t need regular access']],h:'The account controls access and tax. The fund inside it controls how your money is invested.',fact:'You can invest in the same type of fund through different accounts. The account’s tax treatment can make a difference.'},
 {id:'experience',t:'How familiar are you with investing?',s:'We’ll keep the explanations at your level.',o:[['0','I’m starting out','Keep it simple'],['1','I know the basics','I’ve invested a little before'],['2','I’ve invested through ups and downs','I understand that values change']],h:'No investment knowledge is needed to complete this journey. We’ll match the fund for you.',fact:'A balanced fund holds a mix of investments, so you don’t have to build a portfolio one company at a time.'},
 {id:'loss',t:'How comfortable are you with ups and downs?',s:'Imagine R10,000 fell to R8,000. Which response feels most like you?',o:[['0','I’d want to move to something steadier','I prefer very little movement'],['1','I’d prefer a smaller fall','I’m comfortable with a little risk'],['2','I’d give it time, but keep an eye on it','I accept some movement for potential growth'],['3','I’d stay with my long-term plan','I accept bigger swings for growth potential']],h:'There is no right answer. The fund should reflect your comfort with risk, not somebody else’s.',fact:'Company shares offer growth potential, but their values move up and down. Balanced funds combine them with other investments.'},
 {id:'capacity',t:'How flexible is your goal date?',s:'If markets were down when you planned to use the money, what could you do?',o:[['0','I would need the money as planned','A loss would affect essential spending'],['1','I could make a small adjustment','The goal date is fairly firm'],['2','I could wait longer','I have other money for everyday needs'],['3','I could give it several more years','I have plenty of flexibility']],h:'This checks how much risk your plan can absorb, as well as how much risk you feel comfortable taking.',fact:'Matching a fund to your timeframe helps keep your investment and your goal working together.'},
 {id:'tax',t:'Do you know your income-tax rate?',s:'This helps us compare the benefits of different accounts.',o:[['unknown','I’m not sure','No need to look it up'],['low','30% or less','Including if I don’t pay income tax'],['high','More than 30%','My marginal tax rate is above 30%']],h:'If you’re unsure, we won’t assume that a more complex tax structure helps you.',fact:'Tax-free investment accounts shelter returns from South African income, dividends and capital gains tax. Contribution limits apply.'},
 {id:'tfsa',t:'Have you used a tax-free investment account?',s:'Include accounts you hold with other providers.',o:[['none','Not yet','This would be my first'],['some','Yes, and I have some allowance left','We’ll check the amounts later'],['full','My allowance is already used','Show me the other account options'],['unknown','I’m not sure','I’ll confirm before applying']],h:'The allowance is shared across all your tax-free accounts. We’ll check it before you continue.',fact:'You can contribute up to R46,000 per tax year and R500,000 over your lifetime. Investment growth doesn’t use up that allowance.'}
];
const shortMoney=v=>v>=1000000?'R'+(v/1000000).toFixed(v%1000000===0?0:1)+'m':v>=1000?'R'+Math.round(v/1000)+'k':'R'+Math.round(v);
export function growthChart(p,{compact=false,id='growth'}={}){
 const pts=p.points.slice(1),max=Math.max(...pts.map(x=>Math.max(x.value,x.paid)),1),raw=max/4,mag=10**Math.floor(Math.log10(raw)),tick=Math.ceil(raw/mag)*mag,ceiling=tick*4;
 const width=compact?610:1000,height=compact?235:340,left=0,right=0,top=8,bottom=0,w=width-left-right,h=height-top-bottom;
 const barGap=pts.length>25?3:5,barWidth=Math.max(2,w/pts.length-barGap),y=v=>top+h-v/ceiling*h;
 const hasLoss=pts.some(x=>x.value<x.paid),labelEvery=compact?Math.ceil(pts.length/4):Math.ceil(pts.length/6);
 return `<div class="growth-key"><span><i class="contrib-key"></i>Contributions</span><span><i class="growth-key-dot"></i>Potential growth</span>${hasLoss?'<span><i class="loss-key"></i>Potential loss</span>':''}</div><div class="chart-with-axis"><div class="axis-y">${[4,3,2,1,0].map(i=>`<span>${shortMoney(i*tick)}</span>`).join('')}</div><div class="bar-surface"><svg class="growth-bars" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">How your investment could grow</title><desc id="${id}-desc">Year-end contributions and illustrated growth, after modelled fees and before personal tax. ${hasLoss?'Orange marks an illustrated loss relative to contributions. ':''}Not a forecast.</desc>${[0,1,2,3,4].map(i=>`<g><line x1="${left}" x2="${width-right}" y1="${y(i*tick)}" y2="${y(i*tick)}" class="chart-grid-line"/></g>`).join('')}${pts.map((p,i)=>{const x=left+i*w/pts.length+(w/pts.length-barWidth)/2,base=Math.min(p.paid,p.value),growth=Math.max(0,p.value-p.paid),loss=Math.max(0,p.paid-p.value);return `<g class="year-bar" tabindex="0" role="img" aria-label="Year ${p.year}: contributions ${money(p.paid)}, value ${money(p.value)}, ${growth?'growth '+money(growth):'loss '+money(loss)}"><title>Year ${p.year}: ${money(p.value)} value · ${money(p.paid)} contributed</title><rect x="${x}" y="${y(base)}" width="${barWidth}" height="${base/ceiling*h}" class="bar-contribution"/><rect x="${x}" y="${y(p.value)}" width="${barWidth}" height="${growth/ceiling*h}" rx="3" class="bar-growth"/>${loss?`<rect x="${x}" y="${y(p.paid)}" width="${barWidth}" height="${loss/ceiling*h}" class="bar-loss"/>`:''}</g>`}).join('')}</svg><div class="axis-x">${pts.map((p,i)=>i===0||(i+1)%labelEvery===0||i===pts.length-1?`<span style="left:${(i+.5)/pts.length*100}%">${compact?'Y':'Yr '}${p.year}</span>`:'').join('')}</div></div></div>`;
}
export function homeView(calc){const p=project(calc);return `<section class="launch-hero"><div class="hero-copy"><p class="eyebrow">YOUR MONEY. MOVING FORWARD.</p><h1>Make your<br><em>money</em> work<br>for you!</h1><p>Investing doesn’t need to be complicated.<br>Tell us your goal. We’ll match a Sygnia fund to your risk profile and explain your options.</p><div class="hero-actions"><button class="button acid" id="start">Invest today <span>↗</span></button><a href="#how-it-works">How it works</a></div><div class="hero-checks"><span>✓ No adviser fee</span><span>✓ A fund matched to you</span></div><div class="hero-rate"><strong>0.25% <small>+ VAT / year</small></strong><span>Our platform fee. Fund and provider charges are additional. <a href="#fees">See all costs ↗</a></span></div></div><div class="hero-growth"><div class="growth-card-head"><span class="tag">YOUR FUTURE IN NUMBERS</span><span class="mini-note">Illustration</span></div><div id="hero-value"><span class="growth-kicker">${money(calc.monthly)} a month could become</span><strong>${money(p.value)}</strong><p>over ${calc.years} years, after modelled fees</p></div><div id="hero-chart">${growthChart(p,{compact:true,id:'hero'})}</div><div class="hero-sliders"><label>Invest each month <output id="home-monthly-label">${money(calc.monthly)}</output><input id="home-monthly" type="range" min="500" max="10000" step="500" value="${calc.monthly}"></label><label>Give it time <output id="home-years-label">${calc.years} years</output><input id="home-years" type="range" min="5" max="60" step="1" value="${calc.years}"></label></div><p class="chart-assumption">Illustration at ${calc.gross}% yearly growth after fees. Not guaranteed. <a href="#calculator">Change assumptions ↗</a></p></div></section><section class="benefit-ribbon"><div><b>Start small.</b><span>Build a regular investing habit.</span></div><div><b>Let time help.</b><span>Growth can earn growth of its own.</span></div><div><b>Keep it simple.</b><span>Your fund is matched automatically.</span></div></section><section class="how-section" id="how-it-works"><div class="section-head"><div><p class="eyebrow">FROM “ONE DAY” TO DAY ONE</p><h2>Your next step is simple.</h2></div><p>Tell us about your plans.<br>We’ll take care of the fund matching.</p></div><div class="journey-tiles">${[['01','Tell us about you','Your goal, your timeframe and a short risk profile.','violet'],['02','Meet your investment matches','See the account options, your matched fund and why they fit your answers.','aqua'],['03','Choose and apply','Choose an account, review the costs and complete the application.','lime']].map(([n,t,p,c])=>`<article class="journey-tile ${c}"><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="growth-wide section"><div class="section-head"><div><p class="eyebrow">DID YOU KNOW?</p><h2>Your growth can grow, too.</h2></div><p>With returns reinvested, both your contributions and earlier growth can earn further returns.</p></div><div class="growth-explainer"><div><span class="explain-number">${money(p.paid)}</span><p>You contribute over ${calc.years} years</p></div><span class="math-plus">+</span><div><span class="explain-number green">${money(Math.max(0,p.value-p.paid))}</span><p>Illustrated growth after modelled fees</p></div><a href="#calculator" class="button">Explore your numbers ↗</a></div><p class="micro">${calc.gross}% yearly growth after fees, monthly contributions, no starting lump sum, with a ${calc.inc||5}% yearly contribution increase. Illustration only; returns can be negative.</p></section><section class="learn-promo section"><img src="lifestyle.jpg" alt="A woman planning her next step at home" width="1122" height="1402" loading="lazy"><div><p class="eyebrow">INVESTING CAN BE PART OF YOUR EVERYDAY LIFE</p><h2>You don’t need to<br>be an expert to start.</h2><p>A few clear questions. One matched fund. The information you need to take your next step.</p><button class="button" data-start>Find my investment ↗</button><a href="#learn">Learn the basics</a></div></section><section class="section"><div class="section-head"><div><p class="eyebrow">FOUR WAYS TO INVEST</p><h2>An account for your plans.</h2></div><p>We’ll bring the relevant options into your journey, so you don’t have to work this out alone.</p></div><div class="account-teasers">${[['tfsa','Tax-free growth','Keep your investment returns free of South African tax. Limits apply.'],['ra','A stronger retirement','Build retirement savings with potential tax relief on contributions.'],['discretionary','More freedom','Invest without an annual contribution cap or fixed term.'],['endowment','Tax inside the policy','A longer-term option with tax handled by the insurer.']].map(([id,t,p])=>`<a href="#accounts" class="teaser"><span>${ACCOUNTS.find(a=>a.id===id).short}</span><h3>${t}</h3><p>${p}</p><b>↗</b></a>`).join('')}</div></section>`}
export function profileView(q,step,answers,field,esc){const choices=q.id==='access'&&answers.goal!=='retirement'?q.o.filter(([v])=>v!=='retirement'):q.o;return `<div class="flow vibrant-flow"><div class="flow-top"><a href="#home">← Home</a><span>YOUR INVESTMENT STARTS HERE · ${step+1} OF ${newQuestions.length}</span></div><div class="progress" role="progressbar" aria-label="Profile progress" aria-valuemin="0" aria-valuemax="${newQuestions.length}" aria-valuenow="${step+1}"><span style="width:${(step+1)/newQuestions.length*100}%"></span></div><div class="flow-layout"><section class="question"><p class="eyebrow">${step<5?'LET’S BUILD YOUR PLAN':'LET’S FIND YOUR MATCH'}</p><h1 tabindex="-1">${q.t}</h1><p class="lead">${q.s}</p><form id="question-form">${choices?`<fieldset class="choices"><legend class="sr-only">${q.t}</legend>${choices.map(([v,t,s])=>`<label class="choice"><input type="radio" name="${q.id}" value="${v}" ${answers[q.id]===v?'checked':''} required><span><strong>${t}</strong><small>${s}</small></span></label>`).join('')}</fieldset>`:`<div class="fields">${q.f.map(([id,l,min,max])=>field(id,l,'number',answers[id]??'',min,max)).join('')}</div>`}<p id="form-error" class="error" role="alert"></p><div class="flow-actions"><button class="text-button" type="button" id="back">← Back</button><button class="button" type="submit">${step===newQuestions.length-1?'See my investment matches':'Continue'} →</button></div></form><details class="why-ask"><summary>Why this matters</summary><div class="detail-body">${q.h}</div></details></section><aside class="did-you-know"><span class="idea-symbol">✦</span><p class="eyebrow">DID YOU KNOW?</p><h3>${['Small steps add up.','Plan for future you.','Growth can earn growth.','The account makes a difference.','You don’t have to pick shares.','Balance is built in.','Your timeframe matters.','Tax benefits can help.','Your allowance is valuable.'][step]}</h3><p>${q.fact}</p><div class="journey-mini"><span>${Math.round((step+1)/newQuestions.length*100)}%</span><p>of your profile complete</p></div></aside></div></div>`}
export function matchCard(m,{featured=false,years=20}={}){const a=m.account,f=m.fund;return `<article class="investment-match ${featured?'featured':''}"><div class="match-heading"><span class="tag">${featured?'CLOSEST ACCOUNT MATCH':'ANOTHER OPTION'}</span><span class="account-monogram">${a.short}</span></div><h3>${a.name}</h3><p class="match-reason">${m.reason}</p><div class="auto-fund"><span>FUND MATCHED TO YOUR PROFILE</span><strong>${f?'Sygnia '+f.name:'Policy fund eligibility to be confirmed'}</strong><p>${f?m.whyFund:'We won’t assume a fund is available in this insurance policy. Its approved fund list is needed first.'}</p></div>${f?performanceCard(f):''}<ul class="match-benefits"><li>${a.good}</li><li>${f?f.good:'The insurer handles tax administration inside the policy.'}</li></ul><div class="match-keep"><b>Keep in mind</b><p>${a.bad} ${f?f.bad:''}</p></div>${f?`<div class="match-cost"><span>Illustrative annual cost<small>At R100,000 · VAT included</small></span><strong>${percent(totalCost(f))}</strong></div>`:'<p class="micro">Final policy costs require a provider quote.</p>'}<button class="button ${featured?'':'secondary'}" data-match="${a.id}">${m.providerPending?'Explore this application':'Start with this account'} ↗</button><details><summary>Access, fees & fund details</summary><div class="detail-body"><p>${a.access}</p><p>${a.rule}</p>${f?`<p>Fund ${percent(f.ter)} expenses + ${percent(f.tc)} transactions; Money in Motion 0.2875%; provider 0.4025% on first R2m. Provider agreement is pending.</p><p><a href="https://www.sygnia.co.za/blog/fund/${f.url}/" target="_blank" rel="noopener">Sygnia fund details ↗</a></p>`:''}<a href="#fees">Full cost explanation</a></div></details></article>`}
